package local.aicenter.app;
import android.app.Activity;
import android.text.InputType;
import android.view.ViewGroup;
import android.widget.*;
import local.aicenter.core.FactorialDesign;
import local.aicenter.core.AgentRuntime;

/** Local bounded experimental plan and actual-result analysis. Never operates machinery. */
final class FactorialScreen extends LinearLayout {
 static final String EXAMPLE="run,A,B,Y\n1,-1,-1,11.5\n2,-1,-1,13.5\n3,1,-1,12.5\n4,1,-1,14.5\n5,-1,1,2.5\n6,-1,1,4.5\n7,1,1,9.5\n8,1,1,11.5";
 FactorialScreen(Activity a,CenterApplication app,Runnable home,Runnable login){super(a);setOrientation(VERTICAL);LinearLayout bar=new LinearLayout(a);bar.addView(button(a,"立即断开AI",()->{app.disconnect();home.run();}),new LayoutParams(0,LayoutParams.WRAP_CONTENT,1));bar.addView(button(a,"返回AI首页",home),new LayoutParams(0,LayoutParams.WRAP_CONTENT,1));addView(bar);LinearLayout body=new LinearLayout(a);body.setOrientation(VERTICAL);body.setPadding(dp(18),dp(12),dp(18),dp(18));body.addView(label(a,"DOE两水平全因子",24));body.addView(label(a,"每个因素组合需要2至10次独立试验；重复测同一件不能当独立重复。先在工艺记录中定义A–D实际高/低水平，确认安全范围。此工具仅生成编码表，不控制设备。",15));body.addView(label(a,"因素数量",15));Spinner k=new Spinner(a);k.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"2","3","4"}));body.addView(k);body.addView(label(a,"每个组合独立重复次数",15));Spinner r=new Spinner(a);r.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"2","3","4","5","6","7","8","9","10"}));body.addView(r);EditText seed=new EditText(a);seed.setHint("随机种子（整数，可重现顺序）");seed.setText("42");seed.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);body.addView(seed);TextView plan=label(a,"尚未生成试验表",14);plan.setTextIsSelectable(true);body.addView(plan);TextView result=label(a,"等待DOE数据",15);EditText data=new EditText(a);data.setHint("run,A,B,Y；各行填运行编号、-1/+1因素编码、实际Y");data.setMinLines(7);data.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);EditText unit=new EditText(a);unit.setHint("响应单位，例如N·m；无量纲填scalar");body.addView(button(a,"生成随机试验表",()->{if(!allowed(app,login))return;try{String generated=FactorialDesign.plan(k.getSelectedItemPosition()+2,r.getSelectedItemPosition()+2,Long.parseLong(seed.getText().toString().trim()));plan.setText(generated);result.setText("试验表已生成，Y留空；请按随机运行顺序实施并填真实结果。现有输入保留。");}catch(IllegalArgumentException e){result.setText("种子需为64位整数，因素/重复须在支持范围内。");}}));body.addView(button(a,"将试验表放入空白输入区",()->{if(!allowed(app,login))return;if(data.getText().length()>0){result.setText("已有输入未替换，请先另行保存后清空输入。");return;}if(!plan.getText().toString().startsWith("run,")){result.setText("请先生成试验表");return;}data.setText(plan.getText());}));body.addView(label(a,"结果每行：运行编号,A,B[,C,D],Y。表头可用生成的精确表头；编号唯一且覆盖1至总运行数。仅逗号/Tab分隔，不支持引号CSV；缺测、中心点0、不平衡或区组设计拒绝分析。",14));body.addView(data);body.addView(unit);CheckBox confirmed=new CheckBox(a);confirmed.setText("已确认DOE设计、独立重复、随机运行与响应单位");body.addView(confirmed);body.addView(result);LinearLayout plots=new LinearLayout(a);plots.setOrientation(VERTICAL);body.addView(plots);
  android.widget.AdapterView.OnItemSelectedListener changed=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> parent){}public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View view,int position,long id){confirmed.setChecked(false);plots.removeAllViews();plan.setText("尚未生成试验表");result.setText("DOE设计已更改，请重新确认条件。");}};k.setOnItemSelectedListener(changed);r.setOnItemSelectedListener(changed);
  body.addView(button(a,"填入DOE合成示例",()->{if(!allowed(app,login))return;if(data.getText().length()>0){result.setText("已有输入未替换，请先另行保存后清空输入。");return;}if(k.getSelectedItemPosition()!=0)k.setSelection(0);if(r.getSelectedItemPosition()!=0)r.setSelection(0);data.setText(EXAMPLE);unit.setText("N·m");confirmed.setChecked(false);plots.removeAllViews();result.setText("纯合成数据：A/B为两个工艺因素的-1/+1编码，Y为模拟响应；不是推荐工艺或真实试验结果。");}));
  body.addView(button(a,"分析DOE结果",()->{if(!allowed(app,login))return;plots.removeAllViews();try{FactorialDesign.Result calculated=FactorialDesign.analyze(k.getSelectedItemPosition()+2,r.getSelectedItemPosition()+2,data.getText().toString(),unit.getText().toString(),confirmed.isChecked());result.setText(calculated.report());plots.addView(new FactorialPlot(a,calculated),new LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(Math.max(230,calculated.terms.size()*28+70))));app.db.record(java.util.UUID.randomUUID().toString(),AgentRuntime.State.SUCCEEDED,"doe.factorial","computed");}catch(IllegalArgumentException e){result.setText(e.getMessage());}catch(Exception e){result.setText("DOE分析或记录未完成，请检查本地存储；输入未上传。");plots.removeAllViews();}}));body.addView(label(a,"固定效应、完整交互模型；重复误差用于F检验，零误差不报有效p值。未检验残差分布/等方差、未校正多重检验；不能直接证明因果或给最优工艺。两水平不检验曲率，不接受区组/裂区/分数因子/混料设计。\n依据：NIST全因子设计、效应与平衡ANOVA；分布计算沿用已固定版本的Apache Commons Statistics。\n"+FactorialDesign.SOURCE,13));ScrollView scroll=new ScrollView(a);scroll.addView(body);addView(scroll,new LayoutParams(LayoutParams.MATCH_PARENT,0,1));
 }
 private static boolean allowed(CenterApplication app,Runnable login){if(!app.admin.unlocked()){login.run();return false;}return app.stop.enabled();}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private static TextView label(Activity a,String s,int n){TextView t=new TextView(a);t.setText(s);t.setTextSize(n);t.setTextColor(0xff1e302c);return t;}
 private static Button button(Activity a,String s,Runnable r){Button b=new Button(a);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
}
